122 | export function formatDistanceStrict(
123 |   laterDate: DateArg<Date> & {},
124 |   earlierDate: DateArg<Date> & {},
125 |   options?: FormatDistanceStrictOptions,
126 | ): string {
127 |   const defaultOptions = getDefaultOptions();
128 |   const locale = options?.locale ?? defaultOptions.locale ?? defaultLocale;
129 | 
130 |   const comparison = compareAsc(laterDate, earlierDate);
131 | 
132 |   if (isNaN(comparison)) {
133 |     throw new RangeError("Invalid time value");
134 |   }
135 | 
136 |   const localizeOptions = Object.assign({}, options, {
137 |     addSuffix: options?.addSuffix,
138 |     comparison: comparison as -1 | 0 | 1,
139 |   });
140 | 
141 |   const [laterDate_, earlierDate_] = normalizeDates(
142 |     options?.in,
143 |     ...(comparison > 0 ? [earlierDate, laterDate] : [laterDate, earlierDate]),
144 |   );
145 | 
146 |   const roundingMethod = getRoundingMethod(options?.roundingMethod ?? "round");
147 | 
148 |   const milliseconds = earlierDate_.getTime() - laterDate_.getTime();
149 |   const minutes = milliseconds / millisecondsInMinute;
150 | 
151 |   const timezoneOffset =
152 |     getTimezoneOffsetInMilliseconds(earlierDate_) -
153 |     getTimezoneOffsetInMilliseconds(laterDate_);
154 | 
155 |   // Use DST-normalized difference in minutes for years, months and days;
156 |   // use regular difference in minutes for hours, minutes and seconds.
157 |   const dstNormalizedMinutes =
158 |     (milliseconds - timezoneOffset) / millisecondsInMinute;
159 | 
160 |   const defaultUnit = options?.unit;
161 |   let unit: FormatDistanceStrictUnit;
162 |   if (!defaultUnit) {
163 |     if (minutes < 1) {
164 |       unit = "second";
165 |     } else if (minutes < 60) {
166 |       unit = "minute";
167 |     } else if (minutes < minutesInDay) {
168 |       unit = "hour";
169 |     } else if (dstNormalizedMinutes < minutesInMonth) {
170 |       unit = "day";
171 |     } else if (dstNormalizedMinutes < minutesInYear) {
172 |       unit = "month";
173 |     } else {
174 |       unit = "year";
175 |     }
176 |   } else {
177 |     unit = defaultUnit;
178 |   }
179 | 
180 |   // 0 up to 60 seconds
181 |   if (unit === "second") {
182 |     const seconds = roundingMethod(milliseconds / 1000);
183 |     return locale.formatDistance("xSeconds", seconds, localizeOptions);
184 | 
185 |     // 1 up to 60 mins
186 |   } else if (unit === "minute") {
187 |     const roundedMinutes = roundingMethod(minutes);
188 |     return locale.formatDistance("xMinutes", roundedMinutes, localizeOptions);
189 | 
190 |     // 1 up to 24 hours
191 |   } else if (unit === "hour") {
192 |     const hours = roundingMethod(minutes / 60);
193 |     return locale.formatDistance("xHours", hours, localizeOptions);
194 | 
195 |     // 1 up to 30 days
196 |   } else if (unit === "day") {
197 |     const days = roundingMethod(dstNormalizedMinutes / minutesInDay);
198 |     return locale.formatDistance("xDays", days, localizeOptions);
199 | 
200 |     // 1 up to 12 months
201 |   } else if (unit === "month") {
202 |     const months = roundingMethod(dstNormalizedMinutes / minutesInMonth);
203 |     return months === 12 && defaultUnit !== "month"
204 |       ? locale.formatDistance("xYears", 1, localizeOptions)
205 |       : locale.formatDistance("xMonths", months, localizeOptions);
206 | 
207 |     // 1 year up to max Date
208 |   } else {
209 |     const years = roundingMethod(dstNormalizedMinutes / minutesInYear);
210 |     return locale.formatDistance("xYears", years, localizeOptions);
211 |   }
212 | }

