100 | interface DateString {
101 |   date?: string;
102 |   time?: string;
103 |   timezone?: string;
104 | }
105 | 
106 | interface ParsedYear {
107 |   year: number;
108 |   restDateString: string;
109 | }
110 | 
111 | const patterns = {
112 |   dateTimeDelimiter: /[T ]/,
113 |   timeZoneDelimiter: /[Z ]/i,
114 |   timezone: /([Z+-].*)$/,
115 | };
116 | 
117 | const dateRegex =
118 |   /^-?(?:(\d{3})|(\d{2})(?:-?(\d{2}))?|W(\d{2})(?:-?(\d{1}))?|)$/;
119 | const timeRegex =
120 |   /^(\d{2}(?:[.,]\d*)?)(?::?(\d{2}(?:[.,]\d*)?))?(?::?(\d{2}(?:[.,]\d*)?))?$/;
121 | const timezoneRegex = /^([+-])(\d{2})(?::?(\d{2}))?$/;
122 | 
123 | function splitDateString(dateString: string): DateString {
124 |   const dateStrings: DateString = {};
125 |   const array = dateString.split(patterns.dateTimeDelimiter);
126 |   let timeString;
127 | 
128 |   // The regex match should only return at maximum two array elements.
129 |   // [date], [time], or [date, time].
130 |   if (array.length > 2) {
131 |     return dateStrings;
132 |   }
133 | 
134 |   if (/:/.test(array[0])) {
135 |     timeString = array[0];
136 |   } else {
137 |     dateStrings.date = array[0];
138 |     timeString = array[1];
139 |     if (patterns.timeZoneDelimiter.test(dateStrings.date)) {
140 |       dateStrings.date = dateString.split(patterns.timeZoneDelimiter)[0];
141 |       timeString = dateString.substr(
142 |         dateStrings.date.length,
143 |         dateString.length,
144 |       );
145 |     }
146 |   }
147 | 
148 |   if (timeString) {
149 |     const token = patterns.timezone.exec(timeString);
150 |     if (token) {
151 |       dateStrings.time = timeString.replace(token[1], "");
152 |       dateStrings.timezone = token[1];
153 |     } else {
154 |       dateStrings.time = timeString;
155 |     }
156 |   }
157 | 
158 |   return dateStrings;
159 | }
160 | 
161 | function parseYear(dateString: string, additionalDigits: number): ParsedYear {
162 |   const regex = new RegExp(
163 |     "^(?:(\\d{4}|[+-]\\d{" +
164 |       (4 + additionalDigits) +
165 |       "})|(\\d{2}|[+-]\\d{" +
166 |       (2 + additionalDigits) +
167 |       "})$)",
168 |   );
169 | 
170 |   const captures = dateString.match(regex);
171 |   // Invalid ISO-formatted year
172 |   if (!captures) return { year: NaN, restDateString: "" };
173 | 
174 |   const year = captures[1] ? parseInt(captures[1]) : null;
175 |   const century = captures[2] ? parseInt(captures[2]) : null;
176 | 
177 |   // either year or century is null, not both
178 |   return {
179 |     year: century === null ? (year as number) : century * 100,
180 |     restDateString: dateString.slice((captures[1] || captures[2]).length),
181 |   };
182 | }
183 | 
184 | function parseDate(dateString: string, year: number): Date {
185 |   // Invalid ISO-formatted year
186 |   if (year === null) return new Date(NaN);
187 | 
188 |   const captures = dateString.match(dateRegex);
189 |   // Invalid ISO-formatted string
190 |   if (!captures) return new Date(NaN);
191 | 
192 |   const isWeekDate = !!captures[4];
193 |   const dayOfYear = parseDateUnit(captures[1]);
194 |   const month = parseDateUnit(captures[2]) - 1;
195 |   const day = parseDateUnit(captures[3]);
196 |   const week = parseDateUnit(captures[4]);
197 |   const dayOfWeek = parseDateUnit(captures[5]) - 1;
198 | 
199 |   if (isWeekDate) {
200 |     if (!validateWeekDate(year, week, dayOfWeek)) {
201 |       return new Date(NaN);
202 |     }
203 |     return dayOfISOWeekYear(year, week, dayOfWeek);
204 |   } else {
205 |     const date = new Date(0);
206 |     if (
207 |       !validateDate(year, month, day) ||
208 |       !validateDayOfYearDate(year, dayOfYear)
209 |     ) {
210 |       return new Date(NaN);
211 |     }
212 |     date.setUTCFullYear(year, month, Math.max(dayOfYear, day));
213 |     return date;
214 |   }
215 | }
216 | 
217 | function parseDateUnit(value: string): number {
218 |   return value ? parseInt(value) : 1;
219 | }
220 | 
221 | function parseTime(timeString: string): number {
222 |   const captures = timeString.match(timeRegex);
223 |   if (!captures) return NaN; // Invalid ISO-formatted time
224 | 
225 |   const hours = parseTimeUnit(captures[1]);
226 |   const minutes = parseTimeUnit(captures[2]);
227 |   const seconds = parseTimeUnit(captures[3]);
228 | 
229 |   if (!validateTime(hours, minutes, seconds)) {
230 |     return NaN;
231 |   }
232 | 
233 |   return (
234 |     hours * millisecondsInHour + minutes * millisecondsInMinute + seconds * 1000
235 |   );
236 | }
237 | 
238 | function parseTimeUnit(value: string): number {
239 |   return (value && parseFloat(value.replace(",", "."))) || 0;
240 | }
241 | 
242 | function parseTimezone(timezoneString: string): number {
243 |   if (timezoneString === "Z") return 0;
244 | 
245 |   const captures = timezoneString.match(timezoneRegex);
246 |   if (!captures) return 0;
247 | 
248 |   const sign = captures[1] === "+" ? -1 : 1;
249 |   const hours = parseInt(captures[2]);
250 |   const minutes = (captures[3] && parseInt(captures[3])) || 0;
251 | 
252 |   if (!validateTimezone(hours, minutes)) {
253 |     return NaN;
254 |   }
255 | 
256 |   return sign * (hours * millisecondsInHour + minutes * millisecondsInMinute);
257 | }
258 | 
259 | function dayOfISOWeekYear(
260 |   isoWeekYear: number,
261 |   week: number,
262 |   day: number,
263 | ): Date {
264 |   const date = new Date(0);
265 |   date.setUTCFullYear(isoWeekYear, 0, 4);
266 |   const fourthOfJanuaryDay = date.getUTCDay() || 7;
267 |   const diff = (week - 1) * 7 + day + 1 - fourthOfJanuaryDay;
268 |   date.setUTCDate(date.getUTCDate() + diff);
269 |   return date;
270 | }
