272 | // Validation functions
273 | 
274 | // February is null to handle the leap year (using ||)
275 | const daysInMonths = [31, null, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
276 | 
277 | function isLeapYearIndex(year: number): boolean {
278 |   return year % 400 === 0 || (year % 4 === 0 && year % 100 !== 0);
279 | }
280 | 
281 | function validateDate(year: number, month: number, date: number): boolean {
282 |   return (
283 |     month >= 0 &&
284 |     month <= 11 &&
285 |     date >= 1 &&
286 |     date <= (daysInMonths[month] || (isLeapYearIndex(year) ? 29 : 28))
