290 | function validateDayOfYearDate(year: number, dayOfYear: number): boolean {
291 |   return dayOfYear >= 1 && dayOfYear <= (isLeapYearIndex(year) ? 366 : 365);
292 | }
293 | 
294 | function validateWeekDate(_year: number, week: number, day: number): boolean {
295 |   return week >= 1 && week <= 53 && day >= 0 && day <= 6;
296 | }
297 | 
298 | function validateTime(
299 |   hours: number,
300 |   minutes: number,
301 |   seconds: number,
302 | ): boolean {
303 |   if (hours === 24) {
304 |     return minutes === 0 && seconds === 0;
305 |   }
306 | 
307 |   return (
308 |     seconds >= 0 &&
309 |     seconds < 60 &&
310 |     minutes >= 0 &&
311 |     minutes < 60 &&
312 |     hours >= 0 &&
313 |     hours < 25
314 |   );
315 | }
316 | 
317 | function validateTimezone(_hours: number, minutes: number): boolean {
318 |   return minutes >= 0 && minutes <= 59;
319 | }

