  return week >= 1 && week <= 53 && day >= 0 && day <= 6;
}

function validateTime(
  hours: number,
  minutes: number,
  seconds: number,
): boolean {
  if (hours === 24) {
    return minutes === 0 && seconds === 0;
  }

  return (
    seconds >= 0 &&
    seconds < 60 &&
    minutes >= 0 &&
    minutes < 60 &&
    hours >= 0 &&
